#include "../src/game/stage2_actors.hpp"
#include <cassert>
int main(int argc,char**argv){assert(argc==2);shin::AssetStore a(argv[1]);shin::MapData map{100,100,{}};map.cells.resize(10000,{-1,-1,-1,0,0});shin::AppImage blocks{32,32,std::vector<unsigned char>(1024,0)};shin::PlayerPayload p;shin::initialize_player_payload(p,0,0);shin::game::Stage2Actors manager(a,map,blocks,p);assert(manager.spawn(0x1d,100,100,1));for(int i=0;i<100;++i)assert(!manager.spawn(0x1d,100,100,1));assert(manager.targets().size()==1);auto*e=manager.targets()[0];assert(manager.hurt(*e));shin::IndexedSurface f(640,480);for(int i=0;i<30;++i)manager.tick(0,0,f);assert(manager.dead_placements.count(1));assert(!manager.spawn(0x1d,100,100,1));assert(manager.targets().empty());assert(manager.spawn(0x1d,2000,100,2));manager.tick(0,0,f);assert(manager.respawn_records.size()==1&&manager.respawn_records[0].placement==2&&manager.respawn_records[0].x>=1998);assert(!manager.dead_placements.count(2));}
